using System.Collections.Frozen;
using System.Diagnostics.CodeAnalysis;
using System.Text;

namespace L3Lint.Mcp.Content;

/// <summary>
/// The embedded sample payloads under <c>Examples/{brand}/{name}.json</c>, generated by
/// <c>L3Lint.FixtureGen samples</c> from the brand base payloads.
/// </summary>
internal static class Samples
{
    private const string Prefix = "L3Lint.Mcp.Examples.";

    // Resource names keep the folder separator of the build machine, so keys are normalized to "brand/name".
    private static readonly FrozenDictionary<string, string> Resources = typeof(Samples).Assembly.GetManifestResourceNames()
        .Where(n => n.StartsWith(Prefix, StringComparison.Ordinal) && n.EndsWith(".json", StringComparison.Ordinal))
        .ToFrozenDictionary(n => n[Prefix.Length..^".json".Length].Replace('\\', '/'), n => n, StringComparer.Ordinal);

    /// <summary>Gets every sample as "brand/name".</summary>
    public static IReadOnlyList<string> Names { get; } = [.. Resources.Keys.Order(StringComparer.Ordinal)];

    public static bool TryGet(string brand, string name, [NotNullWhen(true)] out string? text)
    {
        text = null;
        if (!Resources.TryGetValue(brand.ToLowerInvariant() + "/" + name.ToLowerInvariant(), out var resource))
        {
            return false;
        }

        using var stream = typeof(Samples).Assembly.GetManifestResourceStream(resource)!;
        using var reader = new StreamReader(stream, Encoding.UTF8);
        text = reader.ReadToEnd();
        return true;
    }
}
